					const ids = this.get(".").map((x) => x.settings.$uuid);
					const key = ids.join(",");
					if (key !== this._cachedIdsKey) {
						this._cachedIdsKey = key;
						this._cachedIds = ids;
					}
					return this._cachedIds;
